// ===== CLINIC CONFIG - Clean 30-Minute Boundary Configuration =====
const cfg = {
  tz: 'Africa/Addis_Ababa',
  calendarId: 'yeabsirawithfate@gmail.com',      // Clinic Google Calendar
  clinicName: 'Denttora Dental Clinic',
  clinicPhone: '+251 11 555 0123',
  clinicEmail: 'yeabsirawithfate@gmail.com',   // Front desk inbox
  openHour: 8,                                 // 8:00 AM
  closeHour: 17,                               // 5:00 PM
  slotMin: 30,                                 // Standard 30-minute appointment slots
  stepMin: 30,                                 // 30-minute boundary grid
  // Discrete 30-minute slot start times from 08:00 AM to 04:30 PM (ends at 17:00)
  slotTimes: [
    '08:00', '08:30', '09:00', '09:30', '10:00', '10:30',
    '11:00', '11:30', '12:00', '12:30', '13:00', '13:30',
    '14:00', '14:30', '15:00', '15:30', '16:00', '16:30'
  ],
  workdays: [1, 2, 3, 4, 5, 6],                // Monday to Saturday (Closed Sunday)
  minNoticeMin: 60,                            // Earliest bookable time from now
  minChangeNoticeMin: 0,                       // Minimum notice to cancel/move
  searchDays: 14,                              // How far get_slots looks
  maxDaysAhead: 60,                            // Furthest bookable day
  durations: { checkup: 30, pain: 30, filling: 30, extraction: 30, root_canal: 60, whitening: 60, braces: 30, other: 30 },
  labels: { checkup: 'Check-up or cleaning', pain: 'Tooth pain', filling: 'Filling', extraction: 'Extraction', root_canal: 'Root canal', whitening: 'Whitening', braces: 'Braces consultation', other: 'Other (front desk will review)' },
};
// ==================================================================
const Z = cfg.tz;
let inp = $input.first().json || {};
if (!inp.action && typeof inp.query === 'string') { try { inp = JSON.parse(inp.query); } catch (e) { /* keep as is */ } }
const now = DateTime.now().setZone(Z);
const s = (v) => (v === undefined || v === null ? '' : String(v).trim());
const action = s(inp.action).toLowerCase();

function normPhone(raw) {
  let p = s(raw).replace(/[^\d+]/g, '');
  if (p.startsWith('00')) p = '+' + p.slice(2);
  if (!p.startsWith('+')) {
    if (p.startsWith('251')) p = '+' + p;
    else if (p.startsWith('0')) p = '+251' + p.slice(1);
    else if (/^[79]\d{8}$/.test(p)) p = '+251' + p;
  }
  return /^\+251\d{9}$/.test(p) ? p : null;
}
const TYPO = { 'gmial.com': 'gmail.com', 'gmai.com': 'gmail.com', 'gamil.com': 'gmail.com', 'gmail.co': 'gmail.com', 'gmail.con': 'gmail.com', 'yaho.com': 'yahoo.com', 'yahooo.com': 'yahoo.com', 'hotmial.com': 'hotmail.com', 'outlok.com': 'outlook.com' };
function checkEmail(raw) {
  const e = s(raw).toLowerCase();
  if (!e) return { ok: true, email: '' };
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(e)) return { ok: false, error: 'invalid_email' };
  const [user, dom] = e.split('@');
  if (TYPO[dom]) return { ok: false, error: 'email_typo', suggestion: user + '@' + TYPO[dom] };
  return { ok: true, email: e };
}
function parsePref(txt, system) {
  const t = s(txt).toLowerCase();
  if (!t) return { none: true };
  const m = t.match(/^(\d{1,2})(?::(\d{2}))?\s*(am|pm)?$/);
  if (!m) return { err: 'invalid_time' };
  const h = +m[1], min = +(m[2] || 0), mer = m[3];
  if (h > 24 || min > 59) return { err: 'invalid_time' };
  const inHours = (h24) => h24 >= cfg.openHour && h24 < cfg.closeHour;
  if (h > 12) return inHours(h) ? { h24: h, min } : { err: 'outside_hours' };
  const std = mer ? [(h % 12) + (mer === 'pm' ? 12 : 0)] : [h % 12, (h % 12) + 12];
  const eth = [6 + (h % 12)];
  let c = system === 'standard' || mer ? std : system === 'ethiopian' ? eth : std.concat(eth);
  c = [...new Set(c.filter(inHours))];
  if (c.length === 0) return { err: 'outside_hours' };
  if (c.length === 1) return { h24: c[0], min };
  const fmt = (h24) => DateTime.fromObject({ hour: h24, minute: min }, { zone: Z }).setLocale('en').toFormat('h:mm a');
  return { ambiguous: c.sort((a, b) => a - b).map(fmt) };
}

const parseDay = (v) => { const d = DateTime.fromISO(s(v), { zone: Z }); return d.isValid ? d.startOf('day') : null; };
const parseSlot = (v) => { const d = DateTime.fromISO(s(v), { setZone: true }); return d.isValid ? d.setZone(Z) : null; };
const lower = (v) => s(v).toLowerCase();

const tiny = { timeMin: now.toISO(), timeMax: now.plus({ minutes: 1 }).toISO(), query: '' };
let lookup = { ...tiny }, day = { ...tiny }, prepError = null;
const err = (error, extra) => { if (!prepError) prepError = { error, ...(extra || {}) }; };

const refMatch = s(inp.reference).match(/(\d{6})/);
const input = {
  category: cfg.durations[lower(inp.category)] ? lower(inp.category) : 'other',
  urgency: lower(inp.urgency) === 'priority' ? 'priority' : 'normal',
  reason: s(inp.reason_text).slice(0, 300),
  name: s(inp.name).replace(/\s+/g, ' ').slice(0, 80),
  source: s(inp.source) || 'chat',
  timeOfDay: ['morning', 'afternoon'].includes(lower(inp.time_of_day)) ? lower(inp.time_of_day) : 'any',
  timeSystem: ['standard', 'ethiopian'].includes(lower(inp.time_system)) ? lower(inp.time_system) : '',
  prefMinutes: null, dateFrom: null, dateTo: null,
  slotStart: null, newSlotStart: null, phone: '', email: '',
  reference: refMatch ? 'DC-' + refMatch[1] : '',
};

if (!['get_slots', 'book', 'find', 'reschedule', 'cancel'].includes(action)) {
  err('unknown_action');
} else {
  if (action !== 'get_slots') {
    input.phone = normPhone(inp.phone);
    if (!input.phone) err('invalid_phone');
  }
  if (!prepError && action === 'book') {
    if (input.name.length < 2) err('missing_name');
    const em = checkEmail(inp.email);
    if (!em.ok) err(em.error, em.suggestion ? { suggestion: em.suggestion } : {});
    else input.email = em.email;
    const sl = parseSlot(inp.slot_start);
    if (!sl) err('invalid_slot');
    else {
      input.slotStart = sl.toISO();
      lookup = { timeMin: sl.startOf('day').toISO(), timeMax: sl.endOf('day').toISO(), query: '' };
    }
  }
  if (!prepError && action === 'get_slots') {
    const from = parseDay(inp.date_from) || now.startOf('day');
    const start = from < now.startOf('day') ? now.startOf('day') : from;
    const to = parseDay(inp.date_to);
    input.dateFrom = start.toISODate();
    input.dateTo = to ? to.toISODate() : null;
    const pr = parsePref(inp.preferred_time, input.timeSystem);
    if (pr.err) err(pr.err);
    else if (pr.ambiguous) err('ambiguous_time', { options: pr.ambiguous });
    else if (!pr.none) input.prefMinutes = pr.h24 * 60 + pr.min;
    lookup = { timeMin: start.toISO(), timeMax: start.plus({ days: cfg.searchDays }).endOf('day').toISO(), query: '' };
  }
  if (!prepError && ['find', 'cancel', 'reschedule'].includes(action)) {
    const q = input.reference ? 'REF' + input.reference.slice(3) : 'PH' + input.phone.slice(1);
    lookup = { timeMin: now.toISO(), timeMax: now.plus({ days: cfg.maxDaysAhead }).toISO(), query: q };
    if (action === 'reschedule') {
      const ns = parseSlot(inp.new_slot_start);
      if (!ns) err('invalid_slot');
      else {
        input.newSlotStart = ns.toISO();
        day = { timeMin: ns.startOf('day').toISO(), timeMax: ns.endOf('day').toISO(), query: '' };
      }
    }
  }
}
if (prepError) { lookup = { ...tiny }; day = { ...tiny }; }
return [{ json: { action, cfg, now: now.toISO(), input, lookup, day, prepError } }];

const P = $('Prepare').first().json;
const cfg = P.cfg || {}, Z = cfg.tz || 'Africa/Addis_Ababa', inp = P.input || {}, act = P.action;
const now = DateTime.fromISO(P.now, { setZone: true }).setZone(Z);
const lookupEvents = $('Collect lookup').first().json.lookupEvents || [];
const dayEvents = $input.first().json.dayEvents || [];

// Standard 30-minute duration & 30-min boundary grid
const slotMin = 30;
const slotTimesList = [
  '08:00', '08:30', '09:00', '09:30', '10:00', '10:30',
  '11:00', '11:30', '12:00', '12:30', '13:00', '13:30',
  '14:00', '14:30', '15:00', '15:30', '16:00', '16:30'
];

// Ethiopian clock formatters
const toEth = (h) => ((h - 6 + 12) % 12) || 12;
const toEthT = (d) => toEth(d.hour) + ':' + d.toFormat('mm');

const label = (dt) => {
  const d = dt.setZone(Z).setLocale('en');
  return d.toFormat('cccc, LLLL d, h:mm a') + ' (' + toEth(d.hour) + ':' + d.toFormat('mm') + ' local)';
};

const slotLabel = (t) => {
  const a = t.setZone(Z).setLocale('en');
  const b = a.plus({ minutes: slotMin });
  return a.toFormat('cccc, LLLL d, h:mm a') + ' to ' + b.toFormat('h:mm a') + ' (' + toEthT(a) + ' to ' + toEthT(b) + ' local)';
};

const MSG = {
  unknown_action: 'Internal error: unknown action. Apologise and give the clinic phone number ' + cfg.clinicPhone + '.',
  invalid_phone: 'The phone number does not look valid. Ask for it again, for example 0912345678.',
  invalid_email: 'The email does not look valid. Ask the patient to type it again.',
  email_typo: 'The email may contain a typo. Ask the patient if they meant the suggestion.',
  missing_name: 'A full name is required. Ask for it.',
  invalid_slot: 'That time is not a valid bookable slot. Call get_slots again and offer the returned times.',
  slot_taken: 'That time was just taken. Call get_slots again and offer new times.',
  too_soon: 'That time is too soon to book online. Offer later slots or the clinic phone number ' + cfg.clinicPhone + '.',
  too_far: 'That date is too far ahead to book online. Offer an earlier date.',
  closed_day: 'The clinic is closed that day (open Monday to Saturday from 8:00 AM to 5:00 PM).',
  outside_hours: 'That time is outside opening hours (8:00 AM to 5:00 PM, Monday to Saturday). Offer a time inside opening hours.',
  ambiguous_time: 'The time is ambiguous. Ask the patient which one they mean, using the options (12-hour format).',
  invalid_time: 'The time could not be understood. Ask the patient to say it like 4:00 PM.',
  no_slots: 'No free slots found for the requested period. The clinic is open Monday to Saturday, 8:00 AM to 5:00 PM. Call ' + cfg.clinicPhone + '.',
  not_found: 'No upcoming booking matches that phone number (and reference). Check the number with the patient or give the clinic phone number.',
  multiple_bookings: 'More than one upcoming booking was found. Ask which one (use the bookings list), then call again with its reference.',
  too_late: 'It is too late to change this booking online. Give the clinic phone number ' + cfg.clinicPhone + '.',
};
const fail = (code, extra) => ({ write: 'none', response: Object.assign({ ok: false, error: code, message: MSG[code] || 'Something went wrong. Give the clinic phone number ' + cfg.clinicPhone + '.' }, extra || {}) });
const out = (d) => [{ json: d }];

if (P.prepError) {
  const { error, ...rest } = P.prepError;
  return out(fail(error, rest));
}

// ---- calendar helpers ----
function evInterval(e) {
  if (!e || e.status === 'cancelled' || e.transparency === 'transparent') return null;
  const st = (e.start && (e.start.dateTime || e.start.date)) || e.start;
  const en = (e.end && (e.end.dateTime || e.end.date)) || e.end;
  if (!st || !en) return null;
  const a = DateTime.fromISO(String(st), { zone: Z }), b = DateTime.fromISO(String(en), { zone: Z });
  return a.isValid && b.isValid ? { a, b } : null;
}
const busyOf = (evs, excludeId) => (Array.isArray(evs) ? evs : []).filter((e) => e && e.id && e.id !== excludeId).map(evInterval).filter(Boolean);
const overlaps = (a, b, busy) => busy.some((x) => a < x.b && b > x.a);

function freeSlots(busy, fromDay, toDay, dur, minStart) {
  const res = [];
  for (let d = fromDay.startOf('day'); d <= toDay; d = d.plus({ days: 1 })) {
    if (!cfg.workdays.includes(d.weekday)) continue;
    const open = d.set({ hour: cfg.openHour, minute: 0, second: 0, millisecond: 0 });
    const close = d.set({ hour: cfg.closeHour, minute: 0, second: 0, millisecond: 0 });
    for (const hhmm of slotTimesList) {
      const [h, mi] = hhmm.split(':').map(Number);
      const t = d.set({ hour: h, minute: mi, second: 0, millisecond: 0 });
      if (t < open || t.plus({ minutes: dur }) > close) continue;
      if (t < minStart) continue;
      if (!overlaps(t, t.plus({ minutes: dur }), busy)) res.push(t);
    }
  }
  return res;
}

function pick(slots, urgent) {
  if (urgent) return slots.slice(0, 3);
  const chosen = [], days = new Set();
  for (const t of slots) {
    if (chosen.length >= 3) break;
    const k = t.toISODate();
    if (!days.has(k)) { days.add(k); chosen.push(t); }
  }
  if (chosen.length < 3) {
    for (const t of slots) {
      if (chosen.length >= 3) break;
      if (chosen.includes(t)) continue;
      if (chosen.every((c) => c.toISODate() !== t.toISODate() || Math.abs(c.diff(t, 'minutes').minutes) >= slotMin)) chosen.push(t);
    }
  }
  return chosen.sort((x, y) => x.toMillis() - y.toMillis());
}

function slotError(t, dur, busy) {
  if (!t || !t.isValid) return 'invalid_slot';
  const e = t.plus({ minutes: dur });
  if (!slotTimesList.includes(t.toFormat('HH:mm')) || t.second !== 0) return 'invalid_slot';
  if (t < now.plus({ minutes: cfg.minNoticeMin })) return 'too_soon';
  if (t > now.plus({ days: cfg.maxDaysAhead })) return 'too_far';
  if (!cfg.workdays.includes(t.weekday)) return 'closed_day';
  const open = t.set({ hour: cfg.openHour, minute: 0, second: 0, millisecond: 0 });
  const close = t.set({ hour: cfg.closeHour, minute: 0, second: 0, millisecond: 0 });
  if (t < open || e > close) return 'outside_hours';
  if (overlaps(t, e, busy)) return 'slot_taken';
  return null;
}

function parseEv(e) {
  const d = String((e && e.description) || '');
  const g = (k) => { const m = d.match(new RegExp('^' + k + ':\\s*(.*)$', 'm')); return m ? m[1].trim() : ''; };
  const ref = g('Ref');
  const iv = evInterval(e);
  if (!ref || !iv) return null;
  const email = g('Email');
  return { id: e.id, ref, name: g('Name'), phone: g('Phone'), email: email === '-' ? '' : email, visit: g('Visit'), start: iv.a, end: iv.b, description: d };
}

const myBookings = () => lookupEvents.map(parseEv).filter(Boolean)
  .filter((b) => b.phone === inp.phone && b.start > now && (!inp.reference || b.ref === inp.reference))
  .sort((x, y) => x.start.toMillis() - y.start.toMillis());
const listOf = (arr) => arr.map((b) => ({ reference: b.ref, visit: b.visit, label: label(b.start), slot_start: b.start.toISO() }));
const newRef = () => 'DC-' + String(Math.floor(100000 + Math.random() * 900000));

// ---- get_slots ----
if (act === 'get_slots') {
  const dur = slotMin;
  const urgent = inp.urgency === 'priority';
  const minStart = now.plus({ minutes: cfg.minNoticeMin });
  const winStart = DateTime.fromISO(P.lookup.timeMin, { setZone: true }).setZone(Z).startOf('day');
  const winEnd = winStart.plus({ days: cfg.searchDays }).endOf('day');
  const busy = busyOf(lookupEvents);
  const all = freeSlots(busy, winStart, winEnd, dur, minStart);

  const dFrom = DateTime.fromISO(inp.dateFrom, { zone: Z }).startOf('day');
  const dTo = inp.dateTo ? DateTime.fromISO(inp.dateTo, { zone: Z }).endOf('day') : dFrom.endOf('day');

  // Check if user specifically requested a single day (today, tomorrow, or a specific date)
  const isSingleDay = !inp.dateTo || (inp.dateFrom === inp.dateTo);

  // If the requested day is a closed day (e.g. Sunday)
  let closedNotice = '';
  if (isSingleDay && !cfg.workdays.includes(dFrom.weekday)) {
    closedNotice = 'The clinic is closed on ' + dFrom.toFormat('cccc') + 's (open Monday to Saturday from 8:00 AM to 5:00 PM).';
  }

  // Filter slots for requested day and time-of-day
  let daySlots = all.filter((t) => t >= dFrom && t <= dTo &&
    (inp.timeOfDay === 'any' || (inp.timeOfDay === 'morning' ? t.hour < 12 : t.hour >= 12)));

  // If user requested today but today hours have passed, or requested day is Sunday:
  // Gracefully offer tomorrow's (or next business day's) slots instead of failing!
  let alternativeNotice = '';
  if (daySlots.length === 0) {
    if (dFrom.toISODate() === now.toISODate()) {
      alternativeNotice = 'Today clinic hours have ended for new bookings. Here are all available 30-minute slots for tomorrow:';
    } else if (closedNotice) {
      alternativeNotice = closedNotice + ' Here are all available 30-minute slots for the next open clinic day:';
    }
    // Find next available day with slots
    const nextDays = all.filter((t) => t > dTo);
    if (nextDays.length > 0) {
      const nextDayStr = nextDays[0].toISODate();
      daySlots = nextDays.filter((t) => t.toISODate() === nextDayStr);
    }
  }

  let pool = daySlots.length ? daySlots : all;
  if (!pool.length) return out(fail('no_slots'));

  // Sort by preferred time if specified
  if (inp.prefMinutes !== null && !urgent) {
    const mins = (t) => t.hour * 60 + t.minute;
    pool = pool.slice().sort((x, y) => Math.abs(mins(x) - inp.prefMinutes) - Math.abs(mins(y) - inp.prefMinutes));
  }

  // When a specific day is requested (today or tomorrow), RETURN ALL 30-MIN SLOTS up to 5:00 PM!
  let chosen;
  if (isSingleDay) {
    chosen = pool.slice().sort((x, y) => x.toMillis() - y.toMillis());
  } else {
    chosen = pick(pool, urgent);
  }

  const note = alternativeNotice || (closedNotice ? closedNotice : '');

  return out({ write: 'none', response: {
    ok: true,
    action: 'get_slots',
    category: inp.category,
    duration_min: dur,
    note: note,
    total_free: pool.length,
    slots: chosen.map((t) => ({ slot_start: t.toISO(), label: slotLabel(t) })),
  } });
}

// ---- find ----
if (act === 'find') {
  const list = listOf(myBookings());
  return out({ write: 'none', response: { ok: true, action: 'find', count: list.length, bookings: list } });
}

// ---- book ----
if (act === 'book') {
  const dur = slotMin;
  const t = DateTime.fromISO(inp.slotStart, { setZone: true }).setZone(Z);
  const code = slotError(t, dur, busyOf(lookupEvents));
  if (code) return out(fail(code));
  const ref = newRef(), e = t.plus({ minutes: dur }), lbl = slotLabel(t), visit = cfg.labels[inp.category] || 'Dental Visit';
  const description = [
    'Ref: ' + ref, 'Name: ' + inp.name, 'Phone: ' + inp.phone, 'Email: ' + (inp.email || '-'),
    'Visit: ' + visit + ' (' + dur + ' min)', 'Patient said: ' + (inp.reason || '-'),
    'Booked via: ' + inp.source, 'Time: ' + lbl,
    'Search keys: PH' + inp.phone.slice(1) + ' REF' + ref.slice(3),
  ].join('\n');
  return out({
    write: 'create',
    event: { summary: inp.name + ' - ' + visit + ' (' + ref + ')', description, start: t.toISO(), end: e.toISO() },
    booking: { reference: ref, patient_name: inp.name, phone: inp.phone, email: inp.email, category: inp.category,
      reason_text: inp.reason, duration_min: dur, urgency: inp.urgency, start_at: t.toISO(), end_at: e.toISO(),
      status: 'booked', source: inp.source },
    logType: 'created', logDetails: 'Booked ' + lbl,
    mail: { type: 'booked', ref, name: inp.name, email: inp.email, phone: inp.phone, visit, reason: inp.reason, label: lbl, oldLabel: '', source: inp.source },
    response: { ok: true, action: 'book', reference: ref, label: lbl, visit, email_will_be_sent: !!inp.email },
  });
}

// ---- cancel / reschedule: find the patient's booking first ----
const mine = myBookings();
if (!mine.length) return out(fail('not_found'));
if (mine.length > 1 && !inp.reference) return out(fail('multiple_bookings', { bookings: listOf(mine) }));
const m = mine[0];
if (m.start < now.plus({ minutes: cfg.minChangeNoticeMin })) return out(fail('too_late'));

if (act === 'cancel') {
  const lbl = label(m.start);
  return out({
    write: 'delete', eventId: m.id,
    booking: { reference: m.ref, status: 'cancelled', start_at: m.start.toISO(), end_at: m.end.toISO() },
    logType: 'cancelled', logDetails: 'Cancelled ' + lbl,
    mail: { type: 'cancelled', ref: m.ref, name: m.name, email: m.email, phone: m.phone, visit: m.visit, reason: '', label: lbl, oldLabel: '', source: inp.source },
    response: { ok: true, action: 'cancel', reference: m.ref, label: lbl },
  });
}

if (act === 'reschedule') {
  const dur = slotMin;
  const t = DateTime.fromISO(inp.newSlotStart, { setZone: true }).setZone(Z);
  const code = slotError(t, dur, busyOf(dayEvents, m.id));
  if (code) return out(fail(code));
  const e = t.plus({ minutes: dur }), lbl = slotLabel(t), oldLbl = label(m.start);
  let description = m.description.replace(/^Time:.*$/m, 'Time: ' + lbl);
  if (/^Rescheduled from:.*$/m.test(description)) description = description.replace(/^Rescheduled from:.*$/m, 'Rescheduled from: ' + oldLbl);
  else description += '\nRescheduled from: ' + oldLbl;
  return out({
    write: 'update', eventId: m.id,
    event: { start: t.toISO(), end: e.toISO(), description },
    booking: { reference: m.ref, status: 'rescheduled', start_at: t.toISO(), end_at: e.toISO() },
    logType: 'rescheduled', logDetails: 'Moved from ' + oldLbl + ' to ' + lbl,
    mail: { type: 'rescheduled', ref: m.ref, name: m.name, email: m.email, phone: m.phone, visit: m.visit, reason: '', label: lbl, oldLabel: oldLbl, source: inp.source },
    response: { ok: true, action: 'reschedule', reference: m.ref, label: lbl },
  });
}
return out(fail('unknown_action'));

const D = $('Decide').first().json;
const cfg = $('Prepare').first().json.cfg;
const m = D.mail;
const esc = (v) => String(v == null ? '' : v).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const wrap = (title, lines) =>
  '<div style="font-family:Arial,sans-serif;max-width:480px;margin:auto;color:#222">' +
  '<h2 style="margin:0 0 8px">' + esc(cfg.clinicName) + '</h2><h3 style="margin:0 0 12px">' + esc(title) + '</h3>' +
  lines.map((l) => '<p style="margin:6px 0">' + l + '</p>').join('') +
  '<p style="color:#666;margin-top:16px">Questions? Chat with us or call ' + esc(cfg.clinicPhone) + '.</p></div>';

const verb = { booked: 'confirmed', rescheduled: 'moved to a new time', cancelled: 'cancelled' }[m.type];
const patientLines = {
  booked: ['Date and time: <b>' + esc(m.label) + '</b>', 'Reference: <b>' + esc(m.ref) + '</b>', 'To change or cancel, chat with us and quote your reference.'],
  rescheduled: ['New time: <b>' + esc(m.label) + '</b>', 'Previous time: ' + esc(m.oldLabel), 'Reference: <b>' + esc(m.ref) + '</b>'],
  cancelled: ['Cancelled appointment: ' + esc(m.label), 'Reference: ' + esc(m.ref), 'To book again, chat with us anytime.'],
}[m.type];
const items = [];
if (m.email) {
  items.push({ json: { kind: 'patient', to: m.email, subject: 'Your appointment is ' + verb + ' (' + m.ref + ')', html: wrap('Your appointment is ' + verb, patientLines) } });
}
const staffLines = [
  'Time: <b>' + esc(m.label) + '</b>' + (m.oldLabel ? '<br>Previous: ' + esc(m.oldLabel) : ''),
  'Patient: ' + esc(m.name) + ' | ' + esc(m.phone) + ' | ' + esc(m.email || 'no email'),
  'Visit: ' + esc(m.visit) + (m.reason ? '<br>Patient said: ' + esc(m.reason) : ''),
  'Reference: ' + esc(m.ref) + ' | Via: ' + esc(m.source),
];
items.push({ json: { kind: 'staff', to: cfg.clinicEmail, subject: '[Booking ' + m.type + '] ' + m.name + ' - ' + m.label, html: wrap('Booking ' + m.type, staffLines) } });
return items;

const D = $('Decide').first().json;
const safe = (n) => { try { return $(n).all(); } catch (e) { return []; } };
const warnings = [];
for (const n of ['Supabase create booking', 'Supabase update booking', 'Supabase log event', 'Send emails']) {
  for (const it of safe(n)) {
    const er = it.json && it.json.error;
    if (er) warnings.push(n + ': ' + (typeof er === 'string' ? er : (er.message || JSON.stringify(er))));
  }
}
const r = D.response || {};
return [{ json: { response: r, warnings, context: { action: r.action || '', reference: r.reference || '' } } }];
